diff --git a/src/error.rs b/src/error.rs
index a607b74..ce4d76b 100644
--- a/src/error.rs
+++ b/src/error.rs
@@ -61,6 +61,10 @@ pub enum BivvyError {
     #[error("Shell error: {message}")]
     ShellError { message: String },

+    /// User cancelled the operation (e.g., pressed Ctrl+D / EOF).
+    #[error("Operation cancelled by user")]
+    UserCancelled,
+
     /// IO error wrapper.
     #[error("IO error: {0}")]
     Io(#[from] std::io::Error),
@@ -70,6 +74,13 @@ pub enum BivvyError {
     Other(#[from] anyhow::Error),
 }

+impl BivvyError {
+    /// Returns true if this error represents a user cancellation.
+    pub fn is_user_cancelled(&self) -> bool {
+        matches!(self, BivvyError::UserCancelled)
+    }
+}
+
 /// Result type alias for Bivvy operations.
 pub type Result<T> = std::result::Result<T, BivvyError>;

@@ -180,4 +191,30 @@ mod tests {
         }
         assert!(returns_error().is_err());
     }
+
+    #[test]
+    fn user_cancelled_displays_message() {
+        let err = BivvyError::UserCancelled;
+        assert!(err.to_string().contains("cancelled"));
+    }
+
+    #[test]
+    fn user_cancelled_is_user_cancelled() {
+        let err = BivvyError::UserCancelled;
+        assert!(err.is_user_cancelled());
+    }
+
+    #[test]
+    fn other_errors_are_not_user_cancelled() {
+        let err = BivvyError::ConfigValidationError {
+            message: "test".into(),
+        };
+        assert!(!err.is_user_cancelled());
+
+        let io_err = BivvyError::Io(std::io::Error::new(
+            std::io::ErrorKind::UnexpectedEof,
+            "eof",
+        ));
+        assert!(!io_err.is_user_cancelled());
+    }
 }
