+///
+/// EOF errors (from Ctrl+D) are converted to `UserCancelled` instead of `Io`.
 fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
-    BivvyError::Io(e.into())
+    let io_err: std::io::Error = e.into();
+    map_io_eof(io_err)
+}
+
+/// Convert an IO error to `UserCancelled` if it represents EOF, otherwise to `Io`.
+fn map_io_eof(e: std::io::Error) -> BivvyError {
+    if e.kind() == std::io::ErrorKind::UnexpectedEof {
+        BivvyError::UserCancelled
+    } else {
+        BivvyError::Io(e)
+    }
 }

 /// Dialoguer theme without the default yellow `?` prefix.
@@ -120,7 +132,7 @@ fn prompt_yes_no(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Resu
