     term.write_line(&prompt.question).map_err(BivvyError::Io)?;
     term.hide_cursor().map_err(BivvyError::Io)?;

+    let styles = YesNoStyles {
+        active_prefix,
+        active_style,
+        inactive_prefix,
+        inactive_style,
+    };
+
+    let result = prompt_yes_no_loop(term, prompt, options, &pad, sel, &styles);
+
+    // Always restore cursor, even on error
+    term.show_cursor().ok();
+
+    result
+}
+
+/// Bundled style configuration for the yes/no prompt.
+struct YesNoStyles {
+    active_prefix: Style,
+    active_style: Style,
+    inactive_prefix: Style,
+    inactive_style: Style,
+}
+
+/// Inner loop for `prompt_yes_no`, extracted so cursor restoration happens in the caller.
+fn prompt_yes_no_loop(
+    term: &Term,
+    prompt: &Prompt,
+    options: &[PromptOption],
+    pad: &str,
+    mut sel: usize,
+    styles: &YesNoStyles,
+) -> Result<PromptResult> {
     loop {
         // Draw option lines
         for (i, opt) in options.iter().enumerate() {
@@ -145,25 +189,27 @@ fn prompt_yes_no(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Resu
                 format!(
                     "{}{} {}",
                     pad,
-                    active_prefix.apply_to("›"),
-                    active_style.apply_to(&opt.label)
+                    styles.active_prefix.apply_to("›"),
+                    styles.active_style.apply_to(&opt.label)
                 )
             } else {
                 format!(
                     "{}{} {}",
                     pad,
-                    inactive_prefix.apply_to("·"),
-                    inactive_style.apply_to(&opt.label)
+                    styles.inactive_prefix.apply_to("·"),
+                    styles.inactive_style.apply_to(&opt.label)
                 )
             };
             term.write_line(&line).map_err(BivvyError::Io)?;
         }
         term.flush().map_err(BivvyError::Io)?;

-        // Read key
-        let key = term.read_key().map_err(BivvyError::Io)?;
+        // Read key, converting EOF to UserCancelled
+        let key = term.read_key().map_err(map_io_eof)?;

         let chosen = match key {
+            // Ctrl+D — treat as cancellation
+            Key::Char('\x04') => return Err(BivvyError::UserCancelled),
             Key::Char('y') | Key::Char('Y') => options.iter().position(|o| o.value == "yes"),
             Key::Char('n') | Key::Char('N') => options.iter().position(|o| o.value == "no"),
             Key::Enter | Key::Char(' ') => Some(sel),
@@ -196,7 +242,6 @@ fn prompt_yes_no(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Resu
                 Style::new().bold().apply_to(answer_text)
             ))
             .map_err(BivvyError::Io)?;
-            term.show_cursor().map_err(BivvyError::Io)?;

             return Ok(PromptResult::String(options[idx].value.clone()));
         }
@@ -382,4 +427,35 @@ mod tests {
         // Verify the theme object can be used (smoke test)
         drop(theme);
     }
+
+    #[test]
+    fn map_dialoguer_eof_returns_user_cancelled() {
+        let eof_io = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "eof");
+        let dialoguer_err: dialoguer::Error = eof_io.into();
+        let err = map_dialoguer_err(dialoguer_err);
+        assert!(err.is_user_cancelled());
+    }
+
+    #[test]
+    fn map_dialoguer_other_io_returns_io_error() {
+        let other_io = std::io::Error::new(std::io::ErrorKind::BrokenPipe, "broken");
+        let dialoguer_err: dialoguer::Error = other_io.into();
+        let err = map_dialoguer_err(dialoguer_err);
+        assert!(!err.is_user_cancelled());
+    }
+
+    #[test]
+    fn map_io_eof_returns_user_cancelled() {
+        let eof = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "");
+        let err = map_io_eof(eof);
+        assert!(err.is_user_cancelled());
+    }
+
+    #[test]
+    fn map_io_eof_passes_through_other_errors() {
+        let other = std::io::Error::new(std::io::ErrorKind::PermissionDenied, "denied");
+        let err = map_io_eof(other);
+        assert!(!err.is_user_cancelled());
+        assert!(matches!(err, crate::error::BivvyError::Io(_)));
+    }
 }

